 * newer entry into the front for the next read. Runs in the background;
 * failures are non-fatal.
 */
async function reconcileFrontFromBacking(
  front: CacheHandler,
  backing: CacheHandler,
  cacheKey: string,
  softTags: string[],
  frontEntry: CacheEntry
