async function mirrorIntoFront(
  front: CacheHandler,
  cacheKey: string,
  entry: CacheEntry
): Promise<void> {
  try {
    await front.set(cacheKey, Promise.resolve(entry))
  } catch {
    // Background warming; failures are non-fatal.
  }
}

