/**
 * Returns the part of `error.stack` after the message, so the stack parser
 * can't mistake message lines for frames (e.g. a line starting with a URL or
 * with "webpack"/"turbopack").
 */
function getUnparsedStackFrames(error: Error, errorName: string): string {
  let stack = String(error.stack)
  const recorded = (error as ErrorWithStackFramesStart)[STACK_FRAMES_START]
  // `error.stack` may have been replaced after we formatted it.
  if (recorded !== undefined && recorded.stack === stack) {
    return stack.slice(recorded.framesStart)
  }
  // Errors printing by `prepareUnsourcemappedStackTrace` are `Error: <message>` so attempt to strip that prefix
  if (stack.startsWith(errorName)) {
    stack = stack.slice(errorName.length)
  }
  if (stack.startsWith(': ')) {
    stack = stack.slice(': '.length)
  }
  if (stack.startsWith(error.message)) {
    stack = stack.slice(error.message.length)
  }
  return stack
}

function shouldIgnoreListGeneratedFrame(file: string): boolean {
  return file.startsWith('node:') || file.includes('node_modules')
}

function shouldIgnoreListOriginalFrame(file: string): boolean {
  return file.includes('node_modules')
}

interface SourcemappableStackFrame extends StackFrame {
  file: NonNullable<StackFrame['file']>
}

interface SourceMappedFrame {
  stack: IgnorableStackFrame
  // DEV only
  code: string | null
}

function createUnsourcemappedFrame(
  frame: SourcemappableStackFrame
): SourceMappedFrame {
  return {
    stack: {
      file: frame.file,
      line1: frame.line1,
      column1: frame.column1,
      methodName: frame.methodName,
      arguments: frame.arguments,
      ignored: shouldIgnoreListGeneratedFrame(frame.file),
    },
    code: null,
  }
}

function ignoreListAnonymousStackFramesIfSandwiched(
  sourceMappedFrames: Array<{
    stack: IgnorableStackFrame
    code: string | null
  }>
) {
  return ignoreListAnonymousStackFramesIfSandwichedGeneric(
    sourceMappedFrames,
    (frame) => frame.stack.file === '<anonymous>',
