function isRevalidatedAfter(
  tag: string,
  entryTimestamp: number,
  workStore: WorkStore,
  logPrefix: string
): boolean {
  const {
    previouslyRevalidatedTags,
    pendingRevalidatedTags,
    requestStartTime,
