/** Send page views to the configured analytics endpoint. */
export async function logPageView(path: string): Promise<void> {
  const event: PageViewEvent = {
    event: 'page_view',
    path,
    occurredAt: new Date().toISOString(),
  }
  const endpoint = process.env.ANALYTICS_ENDPOINT

  if (!endpoint) {
    console.info('[analytics]', event)
    return
  }

  try {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(event),
      cache: 'no-store',
    })

    if (!response.ok) {
      console.error(`[analytics] Failed to log page view: ${response.status}`)
    }
  } catch (error) {
    console.error('[analytics] Failed to log page view', error)
  }
}
